import { createRequire } from 'node:module'
const require = createRequire(import.meta.url)
const { chromium } = require('C:\\Users\\Administrator\\AppData\\Local\\npm-cache\\_npx\\e41f203b7505f1fb\\node_modules\\playwright')

const appOrigin = 'http://127.0.0.1:8099'
const apiOrigin = 'http://172.27.13.11:8080'
const state = { responseCount: 0, body401Paths: [], http401Paths: [], blockedMutationPaths: [], expiredMessageVisible: false, errorName: null }
let browser

try {
  browser = await chromium.launch({ headless: true, executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe' })
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 })
  const page = await context.newPage()

  page.on('response', async response => {
    const url = new URL(response.url())
    if (!url.pathname.startsWith('/prod-api/')) return
    const path = url.pathname.replace(/^\/prod-api/, '')
    state.responseCount++
    if (response.status() === 401) state.http401Paths.push(path)
    try {
      const body = await response.json()
      if (Number(body?.code) === 401) state.body401Paths.push(path)
    } catch {}
  })

  await page.route('**/prod-api/**', async route => {
    const request = route.request()
    const localUrl = new URL(request.url())
    const apiPath = localUrl.pathname.replace(/^\/prod-api/, '') || '/'
    const readOnlyPost = request.method() === 'POST' && apiPath.toLowerCase() === '/system/divisions/list'
    if (request.method() !== 'GET' && !readOnlyPost) {
      state.blockedMutationPaths.push(apiPath)
      await route.abort()
      return
    }
    const target = `${apiOrigin}${apiPath}${localUrl.search}`
    const response = await route.fetch({ url: target })
    await route.fulfill({ response })
  })

  await page.goto(`${appOrigin}/register/add`, { waitUntil: 'domcontentloaded', timeout: 20000 })
  await page.waitForTimeout(10000)
  state.expiredMessageVisible = await page.getByText('登录状态已过期，请重新登录', { exact: true }).isVisible().catch(() => false)
  await context.close()
} catch (error) {
  state.errorName = error?.name || 'Error'
} finally {
  if (browser) await browser.close().catch(() => {})
  console.log(JSON.stringify(state))
}
